import app from 'flarum/common/app';
import Icon from 'flarum/common/components/Icon';
import stringToColor from 'flarum/common/utils/stringToColor';
/** Flarum's own dayjs (with relativeTime + localizedFormat), not a second bundled copy. */
export const dayjs = window.dayjs;
export const NS = 'ernestdefoe-member-desk';
export function t(key, params = {}) {
  // Plurals need numbers; callers often pass formatted ones ("1,234"). ICU formats them back.
  const out = {};
  for (const [k, v] of Object.entries(params)) out[k] = typeof v === 'string' && /^\d{1,3}(,\d{3})*$/.test(v) ? Number(v.replace(/,/g, '')) : v;
  params = out;
  return app.translator.trans(`${NS}.lib.${key}`, params);
}
export function ts(key, params = {}) {
  const out = t(key, params);
  return Array.isArray(out) ? out.join('') : String(out);
}

/** Member Desk's JSON API. */
export function api(method, path, body, params) {
  return app.request({
    method,
    url: `${app.forum.attribute('apiUrl')}/member-desk${path}`,
    body,
    params
  });
}

/** Where a member's page and the list live (admin and forum differ). */

let links;
export const setLinks = l => links = l;
export const desk = () => links;
export function num(n) {
  return (n || 0).toLocaleString();
}
export function date(iso) {
  return iso ? dayjs(iso).format('ll') : '—';
}
export function ago(iso) {
  if (!iso) return ts('never');
  return dayjs(iso).fromNow();
}
export function isForever(iso) {
  return !!iso && dayjs(iso).year() >= 2037;
}
/** An avatar from plain data: the uploaded picture, or the first letter on the username's colour. */
export function avatar(who, size = 'md') {
  const cls = `MemberDesk-avatar MemberDesk-avatar--${size}`;
  if (who.avatarUrl) return m("img", {
    className: cls,
    src: who.avatarUrl,
    alt: "",
    loading: "lazy"
  });
  const letter = (who.displayName || who.username || '?').charAt(0).toUpperCase();
  return m("span", {
    className: cls,
    style: {
      '--avatar-bg': `#${stringToColor(who.username || '?')}`
    },
    "aria-hidden": "true"
  }, letter);
}
export function groupChip(g) {
  if (!g) return null;
  return m("span", {
    className: "MemberDesk-group",
    style: {
      '--group-color': g.color || 'var(--muted-color)'
    }
  }, g.icon ? m(Icon, {
    name: g.icon
  }) : null, g.name);
}

/** Status pills: suspended, unconfirmed, anonymized, banned IP, or "Active". */
export function statusPills(r, compact = false) {
  const out = [];
  if (r.suspendedUntil) {
    out.push(m("span", {
      className: "MemberDesk-pill MemberDesk-pill--danger"
    }, m(Icon, {
      name: "fas fa-ban"
    }), compact || isForever(r.suspendedUntil) ? t('status.suspended_forever') : t('status.suspended_until', {
      date: dayjs(r.suspendedUntil).format('ll')
    })));
  }
  if (!r.confirmed && !r.anonymized) {
    out.push(m("span", {
      className: "MemberDesk-pill MemberDesk-pill--warn"
    }, m(Icon, {
      name: "far fa-envelope"
    }), t('status.unconfirmed')));
  }
  if (r.anonymized) out.push(m("span", {
    className: "MemberDesk-pill MemberDesk-pill--muted"
  }, t('status.anonymized')));
  if (r.bannedIp) out.push(m("span", {
    className: "MemberDesk-pill MemberDesk-pill--danger"
  }, t('status.banned_ip')));
  if (r.isAdmin && !compact) out.push(m("span", {
    className: "MemberDesk-pill MemberDesk-pill--info"
  }, t('status.admin')));
  if (!out.length) out.push(m("span", {
    className: "MemberDesk-pill MemberDesk-pill--ok"
  }, t('status.active')));
  return out;
}
export function errorText(e) {
  const err = e?.response?.errors?.[0];
  if (err?.detail) return err.detail;
  return ts('error.generic');
}
flarum.reg.add('ernestdefoe-member-desk', 'common/util', { dayjs: dayjs,NS: NS,t: t,ts: ts,api: api,setLinks: setLinks,desk: desk,num: num,date: date,ago: ago,isForever: isForever,avatar: avatar,groupChip: groupChip,statusPills: statusPills,errorText: errorText, });